llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Abiraterone, a steroidal molecule with very high assay transfer, has an estimated absolute oral bioavailability of <10% in humans in the fasted state, directly supporting F<20% for a rigid steroid.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Testosterone undecanoate, a steroid ester, showed absolute oral bioavailability of 6.83±3.32% in young women after oral dosing versus IV, providing threshold-relevant evidence of low F for a steroid scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "β-Sitosterol, a sterol with high transferability, had an absolute oral bioavailability of 0.41% in healthy humans, demonstrating that even lipophilic steroids can have very low oral F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Fulvestrant, a steroidal antiestrogen with phenolic/polar character, has low oral bioavailability and requires intramuscular injection, supporting low F for a hydroxylated steroid.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Danazol reached 67% absolute bioavailability only as a fed-state emulsion, showing that formulation and food can raise F for poorly soluble steroids; this does not apply to the unformulated, hydroxylated query steroid.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a hydroxylated, neutral steroid (estriol-like) with high transferability to multiple steroidal drugs whose absolute oral bioavailability is <10% (abiraterone, testosterone undecanoate, sitosterol, fulvestrant). The physicochemical prior of high F is overridden by direct human absolute-bioavailability evidence in closely related scaffolds. The only high-F analogue (danazol) required a fed lipid emulsion, a condition not applicable to the query. Therefore predict low F (<20%).",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself.",
    "No data on its intestinal permeability, solubility, or first-pass conjugation.",
    "Formulation and food effects for the query are unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

